insert into public.study_tests(id,title,subject,grade,level,path,questions) values('genetyka8-v1','Genetyka · średni','Biologia','8','','testy/biologia/genetyka-8.html','[{"no": 1, "question": "Czym jest gen w szkolnym opisie dziedziczenia?", "topic": "DNA i geny", "options": ["Odcinkiem DNA zawierającym informację potrzebną do wytworzenia określonego produktu, np. białka.", "Całą komórką, w której znajduje się jądro.", "Jednym aminokwasem budującym białko.", "Każdą cechą nabytą podczas życia."], "correct": 0, "explanation": "Gen jest fragmentem DNA. Wiele genów zawiera informację o budowie białek, które wpływają na cechy organizmu. Gen nie jest samą cechą ani całą komórką."}, {"no": 2, "question": "Fragment jednej nici DNA ma sekwencję A–T–G–C–C. Jaki fragment drugiej nici jest z nim komplementarny?", "topic": "Budowa DNA", "options": ["U–A–C–G–G", "T–A–C–G–G", "A–T–G–C–C", "T–A–G–C–C"], "correct": 1, "explanation": "W DNA adenina (A) łączy się z tyminą (T), a guanina (G) z cytozyną (C). Dobieramy partnera do każdej zasady po kolei: T–A–C–G–G. U, czyli uracyl, występuje w RNA zamiast tyminy."}, {"no": 3, "question": "Chromosom po skopiowaniu DNA, przed rozdzieleniem chromatyd, składa się z:", "topic": "Chromosomy", "options": ["Jednej chromatydy i jednej gamety.", "Czterech niezależnych chromosomów.", "Dwóch chromatyd siostrzanych połączonych w okolicy centromeru.", "Dwóch jąder komórkowych."], "correct": 2, "explanation": "Po replikacji chromosom ma dwie chromatydy siostrzane, które zawierają kopie DNA. Dopóki są połączone, liczymy je jako jeden chromosom. Dopiero ich rozdzielenie daje oddzielne chromosomy."}, {"no": 4, "question": "Typowa komórka ciała człowieka ma 46 chromosomów. Ile ma prawidłowa gameta człowieka?", "topic": "Liczba chromosomów", "options": ["46", "92", "12", "23"], "correct": 3, "explanation": "Gamety, czyli plemniki i komórki jajowe, mają po jednym chromosomie z każdej pary — 23. Po połączeniu dwóch gamet zygota ma 46 chromosomów."}, {"no": 5, "question": "Który proces jest bezpośrednio związany z mitozą?", "topic": "Mitoza", "options": ["Zwiększanie liczby komórek podczas wzrostu i gojenia ran.", "Zmniejszenie liczby chromosomów o połowę przy tworzeniu gamet.", "Połączenie plemnika z komórką jajową.", "Wymiana genów między rodzicami po narodzinach dziecka."], "correct": 0, "explanation": "Mitoza daje dwie komórki potomne z taką samą liczbą chromosomów jak komórka wyjściowa. Umożliwia wzrost i odnowę tkanek. Redukcja liczby chromosomów zachodzi w mejozie, a łączenie gamet to zapłodnienie."}, {"no": 6, "question": "Komórka mająca 12 chromosomów przechodzi pełną mejozę. Ile chromosomów ma każde z czterech powstałych jąder?", "topic": "Mejoza", "options": ["3", "6", "12", "24"], "correct": 1, "explanation": "Mejoza obejmuje dwa podziały, ale DNA jest kopiowane tylko przed pierwszym. Liczba chromosomów zostaje zmniejszona o połowę: z 12 do 6. Drugi podział rozdziela chromatydy, nie zmniejsza tej liczby ponownie do 3."}, {"no": 7, "question": "Dlaczego liczba chromosomów nie podwaja się w każdym kolejnym pokoleniu człowieka?", "topic": "Mejoza i zapłodnienie", "options": ["Komórka jajowa nie ma żadnych chromosomów.", "Zygota po zapłodnieniu ma zawsze tylko 23 chromosomy.", "Mejoza zmniejsza liczbę chromosomów w gametach do 23, a zapłodnienie przywraca 46.", "Mitoza usuwa wszystkie chromosomy ojca."], "correct": 2, "explanation": "W gametach liczba chromosomów jest zredukowana: 23 w plemniku i 23 w komórce jajowej. Podczas zapłodnienia łączą się ich zestawy: 23 + 23 = 46. Dzięki temu liczba chromosomów pozostaje stała między pokoleniami."}, {"no": 8, "question": "Dwie rośliny mają genotyp Aa, ale jedna jest niższa wskutek niedoboru wody. Co najlepiej wyjaśnia tę różnicę?", "topic": "Genotyp i fenotyp", "options": ["Niedobór wody zawsze zmienia genotyp Aa w aa.", "Fenotyp oznacza wyłącznie zestaw alleli.", "Rośliny o takim samym genotypie muszą zawsze mieć identyczny wygląd.", "Na fenotyp wpływają zarówno genotyp, jak i warunki środowiska."], "correct": 3, "explanation": "Genotyp to informacja genetyczna, a fenotyp to cechy organizmu, np. wysokość. Na ich wykształcenie może wpływać środowisko. Niedobór wody może ograniczyć wzrost bez zmiany alleli Aa."}, {"no": 9, "question": "Wskaż heterozygotę dla genu oznaczonego literą B.", "topic": "Allele", "options": ["Bb", "BB", "bb", "B"], "correct": 0, "explanation": "Heterozygota ma dwa różne allele danego genu, tutaj B i b. BB i bb to homozygoty. Pojedyncza litera B może oznaczać allel w gamecie, ale nie pełny genotyp tej cechy w komórce diploidalnej."}, {"no": 10, "question": "Jakie allele badanego genu mogą znaleźć się w gametach osobnika Aa?", "topic": "Gamety", "options": ["Wyłącznie aa.", "A albo a — każda gameta zawiera jeden z tych alleli.", "Zawsze jednocześnie A i a.", "Tylko A, ponieważ jest dominujący."], "correct": 1, "explanation": "Podczas mejozy allele rozdzielają się do gamet. Dla osobnika Aa możliwe są gamety z A oraz gamety z a, zwykle z jednakowym prawdopodobieństwem. Dominacja nie usuwa allelu a z gamet."}, {"no": 11, "question": "U grochu allel A warunkuje żółte nasiona i dominuje całkowicie nad a, warunkującym zielone nasiona. Jakie jest prawdopodobieństwo zielonych nasion w krzyżówce Aa × Aa?", "topic": "Krzyżówka Aa × Aa", "options": ["50%", "75%", "25%", "0%"], "correct": 2, "explanation": "Każdy rodzic tworzy gamety A i a. Krzyżówka daje AA, Aa, Aa i aa. Zielone nasiona ma tylko aa, czyli jedna z czterech jednakowo prawdopodobnych kombinacji: 25%. To prawdopodobieństwo, a nie gwarantowany wynik w każdej grupie czterech nasion."}, {"no": 12, "question": "Przy całkowitej dominacji A nad a krzyżujemy osobniki Aa i aa. Jakie jest prawdopodobieństwo cechy dominującej u potomstwa?", "topic": "Krzyżówka Aa × aa", "options": ["25%", "75%", "100%", "50%"], "correct": 3, "explanation": "Osobnik Aa tworzy gamety A i a, a osobnik aa tylko a. Potomstwo może mieć Aa albo aa, z jednakowym prawdopodobieństwem. Cechę dominującą ma Aa, więc wynik to 50%."}, {"no": 13, "question": "Przy całkowitej dominacji A nad a jakie genotypy otrzyma potomstwo krzyżówki AA × aa?", "topic": "Krzyżówka AA × aa", "options": ["Wszystkie osobniki będą Aa.", "Wszystkie osobniki będą AA.", "Połowa będzie AA, a połowa aa.", "Wszystkie osobniki będą aa."], "correct": 0, "explanation": "Rodzic AA przekazuje zawsze A, a rodzic aa zawsze a. Każde potomstwo dostaje więc Aa i wykazuje cechę dominującą. Genotyp potomstwa nie jest identyczny z genotypem żadnego z tych rodziców."}, {"no": 14, "question": "U pewnej rośliny fioletowe kwiaty (A) dominują całkowicie nad białymi (a). Dwie rośliny o fioletowych kwiatach mają potomstwo o białych kwiatach. Jakie genotypy mają rodzice?", "topic": "Wnioskowanie o genotypie", "options": ["aa i aa", "Aa i Aa", "AA i AA", "AA i Aa"], "correct": 1, "explanation": "Białe potomstwo ma aa, więc musiało otrzymać a od każdego rodzica. Rodzice mają fioletowe kwiaty, czyli także A. Oba warunki spełnia Aa: każdy rodzic jest heterozygotą."}, {"no": 15, "question": "Które zdanie poprawnie opisuje allel dominujący przy dominacji zupełnej?", "topic": "Dominacja alleli", "options": ["Zawsze daje organizmowi większą siłę.", "Nigdy nie występuje u homozygoty.", "Jego efekt ujawnia się w fenotypie heterozygoty.", "Zawsze występuje częściej w populacji niż allel recesywny."], "correct": 2, "explanation": "Dominacja opisuje relację alleli: w heterozygocie ujawnia się efekt allelu dominującego. Nie oznacza większej częstości w populacji, przewagi fizycznej ani większej przydatności. Efekt ujawnia się też u homozygoty dominującej."}, {"no": 16, "question": "W typowym układzie chromosomów płci u człowieka matka ma XX, a ojciec XY. Jakie jest w szkolnym modelu prawdopodobieństwo potomstwa XY?", "topic": "Dziedziczenie płci", "options": ["0%", "25%", "100%", "Około 50%"], "correct": 3, "explanation": "Komórka jajowa przekazuje X. Plemnik może przekazać X albo Y: powstaje XX albo XY. Obie możliwości są w szkolnym modelu jednakowo prawdopodobne. Wyniki wcześniejszych narodzin nie wyznaczają płci kolejnego dziecka."}, {"no": 17, "question": "Matka ma genotyp Iᴬi (grupa A), a ojciec Iᴮi (grupa B). Jakie jest prawdopodobieństwo dziecka z grupą krwi 0?", "topic": "Grupy krwi AB0", "options": ["25%", "0%", "50%", "100%"], "correct": 0, "explanation": "Możliwe genotypy potomstwa to IᴬIᴮ (AB), Iᴬi (A), Iᴮi (B) i ii (0). Grupa 0 wymaga otrzymania allelu i od obu rodziców. Jedna z czterech jednakowo prawdopodobnych kombinacji daje ii, czyli 25%."}, {"no": 18, "question": "W uproszczonym modelu hemofilia jest cechą recesywną sprzężoną z X. Matka jest zdrową nosicielką XᴴXʰ, a ojciec zdrowy XᴴY. Jaka część ich synów może mieć hemofilię?", "topic": "Cecha sprzężona z płcią", "options": ["100% synów", "50% synów", "0% synów", "25% synów"], "correct": 1, "explanation": "Syn otrzymuje Y od ojca i jeden X od matki. Matka może przekazać Xᴴ albo Xʰ z jednakowym prawdopodobieństwem. Genotypy synów to więc XᴴY (zdrowy) lub XʰY (hemofilia). Wynik 50% dotyczy synów; wśród całego potomstwa chory syn to 25% w szkolnym modelu."}, {"no": 19, "question": "Które zdanie o mutacjach jest prawdziwe?", "topic": "Mutacje", "options": ["Mutacją jest każda zmiana wyglądu bez zmiany materiału genetycznego.", "Mutacje pojawiają się wyłącznie wtedy, gdy organizm ich potrzebuje.", "Są zmianami materiału genetycznego; ich skutki mogą być różne, także obojętne.", "Każda mutacja musi natychmiast spowodować śmierć."], "correct": 2, "explanation": "Mutacja to zmiana materiału genetycznego. Może dotyczyć sekwencji DNA, budowy lub liczby chromosomów. Jej skutek może być szkodliwy, obojętny albo korzystny — mutacje nie powstają celowo na potrzeby organizmu."}, {"no": 20, "question": "Promieniowanie UV wywołało mutację wyłącznie w komórce skóry człowieka. Czy ta mutacja zostanie przekazana jego dzieciom podczas rozmnażania płciowego?", "topic": "Mutageny i dziedziczenie", "options": ["Tak, każda mutacja w dowolnej komórce trafia do gamet.", "Tak, ponieważ UV zawsze zmienia wszystkie komórki ciała.", "Nie, ponieważ promieniowanie UV nie może powodować mutacji.", "Nie, ponieważ nie zaszła w komórkach dających początek gametom."], "correct": 3, "explanation": "UV jest czynnikiem mutagennym: może uszkadzać DNA. Dziecko otrzymuje jednak materiał genetyczny z gamet, a nie z komórek skóry rodzica. Mutacja ograniczona do komórki skóry nie jest w ten sposób dziedziczona."}]'::jsonb);
